package com.bank.demat.model;

import jakarta.persistence.*;
import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "demat_accounts")
public class DematAccount {

    @Id
    @Column(name = "demat_id")
    private String dematId;

    @Column(name = "holder_name")
    private String holderName;

    private String pan;
    private String status;

    // LAZY (default for @OneToMany): holdings loaded ONLY when getHoldings() called
    // Hibernate creates a PersistentBag proxy — triggers SQL on first access
    @OneToMany(mappedBy = "dematAccount", fetch = FetchType.LAZY)
    private List<StockHolding> holdings = new ArrayList<>();

    protected DematAccount() {}

    public String getDematId() { return dematId; }
    public String getHolderName() { return holderName; }
    public String getPan() { return pan; }
    public List<StockHolding> getHoldings() { return holdings; }
}
```

