package com.bank.demat.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "stock_holdings")
public class StockHolding {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // LAZY: override the default EAGER for @ManyToOne!
    // Default EAGER causes: every holding query also loads the full DematAccount
    @ManyToOne(fetch = FetchType.LAZY)  // ← CRITICAL: override default EAGER!
    @JoinColumn(name = "demat_id")
    private DematAccount dematAccount;

    private String symbol;
    private int quantity;

    @Column(name = "avg_price")
    private BigDecimal avgPrice;

    protected StockHolding() {}

    public String getSymbol() { return symbol; }
    public int getQuantity() { return quantity; }
    public BigDecimal getAvgPrice() { return avgPrice; }
    public DematAccount getDematAccount() { return dematAccount; }
}
