package com.bank.demat.dto;

import com.bank.demat.model.DematAccount;
import java.math.BigDecimal;
import java.util.List;

public record DematView(
    String dematId, String holderName, int holdingCount,
    List<HoldingDetail> holdings
) {
    public record HoldingDetail(String symbol, int quantity, BigDecimal avgPrice) {}

    public static DematView from(DematAccount d) {
        return new DematView(d.getDematId(), d.getHolderName(), d.getHoldings().size(),
            d.getHoldings().stream()
                .map(h -> new HoldingDetail(h.getSymbol(), h.getQuantity(), h.getAvgPrice()))
                .toList());
    }
}
