// ─── File: .../service/DematService.java ───
package com.bank.demat.service;

import com.bank.demat.dto.DematView;
import com.bank.demat.model.*;
import com.bank.demat.repository.*;
import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.hibernate.Hibernate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class DematService {

    private final DematAccountRepository dematRepo;
    private final StockHoldingRepository holdingRepo;
    private final EntityManager entityManager;

    // ═══ CORRECT: JOIN FETCH inside @Transactional ═══
    @Transactional(readOnly = true)
    public DematView getWithHoldings(String dematId) {
        log.info("[JOIN FETCH] Loading demat {} with holdings — 1 query");
        DematAccount demat = dematRepo.findByIdWithHoldings(dematId)
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + dematId));
        return DematView.from(demat);  // holdings already loaded — no lazy issue
    }

    // ═══ Hibernate.initialize(): force lazy load within active session ═══
    @Transactional(readOnly = true)
    public DematView getWithInitialize(String dematId) {
        DematAccount demat = dematRepo.findById(dematId).orElseThrow();
        // Holdings are LAZY — not loaded yet
        Hibernate.initialize(demat.getHoldings());  // FORCE load NOW (within TX)
        // Still fires a separate query — JOIN FETCH is better!
        log.info("[Hibernate.initialize] Holdings loaded: {}", demat.getHoldings().size());
        return DematView.from(demat);
    }

    // ═══ getReference (getById): LAZY PROXY — no DB hit ═══
    @Transactional
    public void addHoldingEfficiently(String dematId, String symbol, int qty, java.math.BigDecimal price) {
        // getReference returns a PROXY — does NOT query DB!
        // Useful for setting FK without loading the entire parent entity
        DematAccount dematProxy = entityManager.getReference(DematAccount.class, dematId);
        // dematProxy is a LAZY PROXY — no SELECT executed yet!
        // Only the ID is set. Accessing other fields would trigger SELECT.

        StockHolding holding = new StockHolding();
        // holding.setDematAccount(dematProxy); // sets FK without loading full DematAccount
        holdingRepo.save(holding);
        log.info("[getReference] Holding added with proxy — NO SELECT on demat_accounts!");
    }

    // ═══ findById: IMMEDIATE DB hit ═══
    @Transactional(readOnly = true)
    public DematView getBasicInfo(String dematId) {
        // findById: hits DB IMMEDIATELY, returns Optional
        DematAccount demat = dematRepo.findById(dematId).orElseThrow();
        // SQL: SELECT * FROM demat_accounts WHERE demat_id = ?
        log.info("[findById] Loaded demat {} — DB hit occurred", dematId);
        // Holdings are LAZY — accessing them HERE (within TX) would trigger another query
        // OUTSIDE TX → LazyInitializationException!
        return new DematView(demat.getDematId(), demat.getHolderName(), 0, java.util.List.of());
    }

    // ═══ BAD: accessing lazy collection OUTSIDE TX → LazyInitializationException ═══
    // This method returns the entity to the controller.
    // If controller accesses holdings → session is closed → EXCEPTION!
    // With OSIV=false (correct setting), this manifests immediately.
    // With OSIV=true (anti-pattern), it works BUT holds connection during view rendering.
    public DematAccount getEntityDirectly(String dematId) {
        // DO NOT return entities to controller!
        // Always map to DTO within @Transactional method.
        return dematRepo.findById(dematId).orElseThrow();
        // If controller calls entity.getHoldings() → LazyInitializationException!
    }
}
```

