    @GetMapping("/{id}/with-holdings")
    public DematView withHoldings(@PathVariable String id) {
        return dematService.getWithHoldings(id);
    }

    @GetMapping("/{id}/with-initialize")
    public DematView withInitialize(@PathVariable String id) {
        return dematService.getWithInitialize(id);
    }

    @GetMapping("/{id}/basic")
    public DematView basicInfo(@PathVariable String id) {
        return dematService.getBasicInfo(id);
    }
}
