    @Test
    void shouldLoadDematWithJoinFetch() {
        DematAccount demat = mock(DematAccount.class);
        when(demat.getDematId()).thenReturn("DEM-001");
        when(demat.getHolderName()).thenReturn("Rajesh");
        when(demat.getHoldings()).thenReturn(List.of());
        when(dematRepo.findByIdWithHoldings("DEM-001")).thenReturn(Optional.of(demat));

        DematView view = service.getWithHoldings("DEM-001");

        assertThat(view.dematId()).isEqualTo("DEM-001");
        verify(dematRepo).findByIdWithHoldings("DEM-001");
    }
}
